-- The Investor table and the INVESTOR login link (T278), generated by Prisma from schema.prisma,
-- plus the role CHECK rewritten by hand at the end: each role links to exactly its own record.

-- CreateEnum
CREATE TYPE "InvestorType" AS ENUM ('DIRECT_BUYER', 'WHOLESALER', 'IBUYER');

-- CreateEnum
CREATE TYPE "InvestorStatus" AS ENUM ('ACTIVE', 'INACTIVE');

-- AlterTable
ALTER TABLE "User" ADD COLUMN     "investorId" TEXT;

-- CreateTable
CREATE TABLE "Investor" (
    "id" TEXT NOT NULL,
    "companyName" TEXT NOT NULL,
    "contactName" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "phone" TEXT,
    "investorType" "InvestorType" NOT NULL,
    "status" "InvestorStatus" NOT NULL DEFAULT 'ACTIVE',
    "proofOfFundsExpiresAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Investor_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "Investor_email_key" ON "Investor"("email");

-- CreateIndex
CREATE UNIQUE INDEX "User_investorId_key" ON "User"("investorId");

-- AddForeignKey
ALTER TABLE "User" ADD CONSTRAINT "User_investorId_fkey" FOREIGN KEY ("investorId") REFERENCES "Investor"("id") ON DELETE SET NULL ON UPDATE CASCADE;



-- AlterCheck (hand-written): an AGENT links to an Agent only, an INVESTOR to an Investor only,
-- and an OPS user to neither.
ALTER TABLE "User" DROP CONSTRAINT "User_role_link_check";
ALTER TABLE "User" ADD CONSTRAINT "User_role_link_check" CHECK (
    (role = 'AGENT' AND "agentId" IS NOT NULL AND "investorId" IS NULL)
    OR (role = 'INVESTOR' AND "investorId" IS NOT NULL AND "agentId" IS NULL)
    OR (role = 'OPS' AND "agentId" IS NULL AND "investorId" IS NULL)
);
